const j = $json;
const zone = 'Asia/Kolkata';
const today = DateTime.now().setZone(zone).startOf('day');
let days_offset = null;
if (j.due_date) {
  let due = DateTime.fromISO(String(j.due_date), { zone: 'utc' }).setZone(zone);
  if (!due.isValid) { due = DateTime.fromISO(String(j.due_date)).setZone(zone); }
  if (due.isValid) {
    due = due.startOf('day');
    days_offset = Math.round(today.diff(due, 'days').days);
  }
}
return { ...j, days_offset };

