const j = $json;
let aiText = '';
try {
  if (Array.isArray(j.output) && j.output[0] && j.output[0].content && j.output[0].content[0]) {
    aiText = j.output[0].content[0].text || '';
  } else if (typeof j.text === 'string') { aiText = j.text; }
} catch (e) { aiText = ''; }
const name = j.client_name || 'there';
const due = j.due_date ? String(j.due_date).slice(0, 10) : '';
const link = j.payment_link ? '<p>Pay securely here: <a href="' + j.payment_link + '">' + j.payment_link + '</a></p>' : '';
const fallback = '<p>Hi ' + name + ',</p>' +
  '<p>This is a ' + (j.stage_label || 'payment reminder') + ' regarding invoice <b>' + j.invoice_id + '</b> for ' + (j.currency || '') + ' ' + j.amount + ', due on ' + due + '.</p>' +
  link + '<p>Thank you.</p>';
const message_body = (aiText && aiText.trim()) ? aiText : fallback;
const wa_text = 'Hi ' + name + ', ' + (j.stage_label || 'reminder') + ' for invoice ' + j.invoice_id + ': ' + (j.currency || '') + ' ' + j.amount + ' due ' + due + '.' + (j.payment_link ? ' Pay: ' + j.payment_link : '');
return { ...j, message_body, wa_text };
